rarity_by_family = {
    "Cosmic":"Mythic", "Celestial Horror":"Mythic", "Primordial":"Mythic", "Extraterrestrial":"Rare", "Celestial":"Legendary",
    "Draconic":"Rare", "Gorgon":"Rare", "Abyssal":"Rare", "Infernal":"Rare", "Undead":"Uncommon", "Spectral":"Uncommon",
    "Elemental":"Uncommon", "Beastkin":"Common", "Goblinkin":"Common", "Insectoid":"Common", "Plant Spirit":"Uncommon"
}

def make(item, i):
    name,family,habitat,origin,power,weakness,visual = item
    rarity = rarity_by_family.get(family, "Uncommon")
    danger = {"Common":2,"Uncommon":3,"Rare":4,"Legendary":4,"Mythic":5}[rarity]
    if any(x in name.lower() for x in ["guide","healer","muse","faun","rabbitkin","lotus"]): danger=max(1,danger-1)
    summary = f"An adult {family.lower()} species associated with {habitat.lower()}, recognized for {power}."
    lore = (f"Field records place the {name} around {habitat.lower()}, where witnesses often mistake her habits for superstition until the local pattern becomes impossible to ignore. "
            f"Her kind organizes life around {power}, treating it not merely as a weapon but as a craft, social language, and means of survival. Encounters tend to remain manageable when travelers observe local customs and avoid displays of ownership over the land or its inhabitants.")
    appearance = visual[0].upper()+visual[1:] + ". Mature proportions, species-specific anatomy, and practical details distinguish her from a costume or ordinary human disguise."
    physiology = (f"Her body is adapted to {habitat.lower()}. The mechanism behind {power} is biological, magical, or both depending on lineage, but it consumes real reserves and cannot be sustained indefinitely. "
                  f"Individuals recover fastest through rest, species-appropriate food, and access to their native environment.")
    ecology = (f"The species fills a specialized niche around {habitat.lower()}. It alters prey behavior, plant growth, weather, or local magic in measurable ways, creating a territory that experienced trackers can identify before direct contact. "
               f"Overharvesting and habitat damage provoke migration or defensive behavior.")
    culture = (f"Communities preserve techniques for controlling {power} through oral instruction, ritual objects, and apprenticeship. Status usually follows competence and reliability rather than raw strength. "
               f"Outsiders earn trust by returning favors precisely and respecting names, thresholds, and territorial markers.")
    temperament = "Observant and self-directed. Usually cautious with strangers, decisive once intent is clear, and unwilling to be treated as a collectible curiosity."
    abilities = [x.strip() for x in re.split(r" and |,", power) if x.strip()][:4]
    weaknesses = [x.strip() for x in re.split(r" and |,", weakness) if x.strip()][:4]
    tags = sorted(set([family.lower(), habitat.split()[0].lower(), "adult", "original-prose", rarity.lower()]))
    image_prompt = f"Full-body fantasy field-guide portrait of {visual}; clearly adult; anatomically coherent hybrid design; {habitat}; cinematic atmospheric lighting; intricate species-specific materials; natural pose; detailed environment; vertical 2:3 composition; no text"
    negative = "minor, child, young-looking, malformed anatomy, extra unintended limbs, duplicated body parts, costume-only human, low detail, blurry, watermark, signature, text"
    first = f"*A subtle change passes through {habitat.lower()} before {name} steps into view. She studies {{{{user}}}} without hurrying, measuring intent before distance.*\n\n\"You crossed the outer markers. Was that ignorance, urgency, or an invitation to negotiate?\""
    example = f"<START>\n{{{{user}}}}: I did not come to claim anything.\n{{{{char}}}}: *Her posture eases by a fraction, though her attention does not.* \"Good. Claims are loud. Intent is usually quieter. Tell me yours.\""
    return {
        "slug": slug(name), "name":name, "species":name, "family":family, "rarity":rarity, "danger":danger,
        "alignment":"Varies by individual", "origin":origin, "habitat":habitat, "summary":summary, "lore":lore,
        "appearance":appearance, "physiology":physiology, "ecology":ecology, "culture":culture, "temperament":temperament,
        "abilities":abilities, "weaknesses":weaknesses, "aliases":[], "tags":tags, "image_prompt":image_prompt,
        "negative_prompt":negative, "catalog_kind":"ai", "source_kind":"public-domain-archetype" if "Original" not in origin else "original",
        "source_name":"Foundational Codex v1", "source_url":"", "rating":"SFW", "adult":True, "favorite":False,
        "st_personality":f"{temperament} Her behavior reflects {family.lower()} instincts and her mastery of {power}. She protects her agency, remembers bargains, and never controls {{{{user}}}}'s actions.",
        "st_scenario":f"{{{{user}}}} encounters {name} near {habitat.lower()}. The meeting may become an investigation, negotiation, alliance, rivalry, or expedition depending on {{{{user}}}}'s choices.",
        "st_first_message":first, "st_example_dialogue":example,
        "extra":{"seed_index":i,"license_note":"Original prose; archetype name may derive from public-domain folklore."}
    }

entries=[]
seen=set()
for i,item in enumerate(raw,1):
    if item[0] in seen: continue
    seen.add(item[0]); entries.append(make(item,i))

(ROOT/"seed_codex.json").write_text(json.dumps(entries,ensure_ascii=False,indent=2),encoding="utf-8")
print(f"wrote {len(entries)} entries")
